const listPOs = `-- name: ListPOs :many
SELECT po.id, po.document_number, po.status, po.total, po.expected_date, po.created_at, po.store_id, po.warehouse_id,
       sp.name AS supplier_name, w.code AS warehouse_code, s.name AS store_name
FROM purchase_orders po
JOIN suppliers sp ON sp.id = po.supplier_id
JOIN warehouses w ON w.id = po.warehouse_id
LEFT JOIN stores s ON s.id = po.store_id LEFT JOIN org_units o ON o.id = s.org_unit_id
WHERE po.company_id = $1
  AND ($2::bool OR (po.store_id IS NOT NULL AND EXISTS (SELECT 1 FROM unnest($3::text[]) sp2 WHERE o.path <@ sp2::ltree)))
  AND ($4::uuid IS NULL OR po.store_id = $4::uuid)
  AND ($5::uuid IS NULL OR po.supplier_id = $5::uuid)
  AND ($6::text = '' OR po.status = $6::text)
  AND ($7::text = '' OR po.document_number ILIKE '%' || $7::text || '%')
ORDER BY po.created_at DESC
LIMIT $9 OFFSET $8
`

